from html.parser import HTMLParser
from pathlib import Path
import re
s=Path('index.html').read_text()
class Check(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=[]; self.links=[]; self.posts=0; self.projects=0; self.images=[]; self.stack=[]; self.errors=[]
    def inspect(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a:self.ids.append(a['id'])
        if tag=='a':self.links.append(a.get('href',''))
        if tag=='article' and a.get('class')=='post':self.posts+=1
        if tag=='article' and a.get('class')=='project':self.projects+=1
        if tag in ('img','image'):self.images.append(a.get('src',a.get('href','')))
    def handle_starttag(self, tag, attrs):
        self.inspect(tag,attrs)
        if tag not in ('meta','link','input','br','hr'): self.stack.append(tag)
    def handle_startendtag(self, tag, attrs):self.inspect(tag,attrs)
    def handle_endtag(self,tag):
        if not self.stack or self.stack[-1]"'!=tag:self.errors.append((tag,self.stack[-4:]))
        else:self.stack.pop()
c=Check();c.feed(s)
assert len(c.ids)==len(set(c.ids)), '"'Duplicate IDs'
assert all(x[1:] in c.ids for x in c.links if x.startswith('#') and x"'!='"'#'), 'Broken section link'
assert c.projects==4 and c.posts==6
assert not c.images
assert 'scrollIntoView' not in s
assert not c.errors, c.errors
assert not c.stack,c.stack
article=re.search(r'<div class=\"article-body\">(.*?)</div>',s,re.S).group(1)
about=re.search(r'<div class=\"about-intro\">(.*?)<ul',s,re.S).group(1)
words=lambda html:len(re.sub('<["'^>]+>'"',' ',html).split())
print('PASS: HTML nesting, unique IDs, internal links, project and post counts, inline imagery')
print(f'Featured essay: {words(article)} words. Biography: {words(about)} words including heading.')
print('Only root output file: '+', '.join(x.name for x in Path('.').iterdir() if x.is_file()))
