class Element {
  constructor(dataset={}) {this.dataset=dataset;this.attrs={};this.events={};this.style={};this.children=[];this.hidden=false;this.content='';}
  setAttribute(k,v){this.attrs[k]=v;}
  addEventListener(k,fn){this.events[k]=fn;}
  fire(k,event={}){this.events[k]?.(event);}
  replaceChildren(){this.children=[];}
  append(...children){this.children.push(...children);}
  showModal(){this.open=true;}
  close(){this.open=false;this.fire('close');}
  reportValidity(){return true;}
  reset(){this.resetCalled=true;}
}
const root=new Element({theme:'light'});
const selectors={};
for(const id of ['.theme-toggle','meta[name=\"theme-color\"]','.filter-status','#project-dialog','#dialog-title','#dialog-meta','#dialog-copy','.dialog-close','#newsletter-form','#newsletter-message'])selectors[id]=new Element();
const filters=['All','Design','Data','Freelancing','Field notes'].map(filter=>new Element({filter}));
const posts=['Design','Field notes','Design','Data','Field notes','Freelancing'].map(tag=>new Element({tag}));
const projects=['tidepool','ledger','delay','handbook'].map(project=>new Element({project}));
let stored={};
const context={document:{documentElement:root,body:new Element(),querySelector:s=>selectors[s],querySelectorAll:s=>s==='[data-filter]'?filters:s==='.post[data-tag]'?posts:projects,createElement:()=>new Element()},localStorage:{getItem:k=>stored[k]||null,setItem:(k,v)=>stored[k]=v},matchMedia:()=>({matches:false,addEventListener(){}})};
vm.runInNewContext(scripts[1],context);
const assert=(condition,msg)=>{if("'!condition)throw Error(msg);};
selectors['"'.theme-toggle'].fire('click');
assert(root.dataset.theme==='dark'&&stored['maya-theme']==='dark','Theme switch');
selectors['.theme-toggle'].fire('click');
assert(root.dataset.theme==='light','Theme restore');
const expected=[6,2,1,1,2];
filters.forEach((filter,i)=>{filter.fire('click');assert(posts.filter(p=>"'!p.hidden).length===expected[i],'"'Filter '+filter.dataset.filter);assert(filter.attrs['aria-pressed']==='true','Active filter');});
projects.forEach(project=>{project.fire('click');assert(selectors['#project-dialog'].open,'Open case study');assert(selectors['#dialog-copy'].children.length===4,'Case study content');selectors['.dialog-close'].fire('click');assert("'!selectors['"'#project-dialog'].open&&context.document.body.style.overflow==='','Close and scroll restore');});
let prevented=false;
selectors['#newsletter-form'].fire('submit',{preventDefault(){prevented=true;},currentTarget:selectors['#newsletter-form']});
assert(prevented&&selectors['#newsletter-form'].resetCalled,'Newsletter preview');
assert(selectors['#newsletter-message'].textContent.includes('doesn’t collect'),'Honest newsletter feedback');
console.log('PASS: theme persistence, all five filters, all four case-study dialogs, scroll restoration, newsletter feedback');
